from lib import *
S = SS('n30')
steps = [
    step("time.Time 的 form 绑定(进程时区设为 America/New_York):默认按 RFC3339,字符串里带 Z 就是 UTC(Def → 10:00:00Z);time_format 写 \"2006-01-02\" 而没写时区时按 time.Local 解析(Day → 2024-05-01T00:00:00-04:00);加 time_utc:\"1\" 按 UTC(DayU → 00:00:00Z);time_location:\"Asia/Shanghai\" 按上海时区(DayS → +08:00);time_format:\"unix\" / \"unixmilli\" 把整数当时间戳,得到的是 Local 时区的时间(06:00:00-04:00,即 10:00Z)。", t=tl(S(1)), mark=lidx(S(1), 'Day   2024-05-01T00:00:00-04:00', 'DayU  2024-05-01T00:00:00Z', 'DayS  2024-05-01T00:00:00+08:00'), done=lidx(S(1), 'Def   2024-05-01T10:00:00Z', 'Unix  2024-05-01T06:00:00-04:00', 'UnixM'), kv=KV([['不写时区', '按 time.Local,换机器时区就变'], ['time_utc:"1"', '按 UTC'], ['time_location', '按指定时区'], ['unix / unixmilli', '整数时间戳,结果是 Local 时间']], ['不写时区'])),
    step("time.Time 的错误与空值:?t=2024-05-01 与默认 RFC3339 不符,err 是 parsing time … cannot parse \"\" as \"T\";?t= 空值不报错,保持零时间;+08:00 要写成 %2B08:00(查询串里没编码的加号会变成空格,?t=2024-05-01+10:00:00 就解析失败);?d=2024-02-30 报 day out of range。JSON 里的 time.Time 只认 RFC3339:\"2024-05-01\" 报同样的错,数字 1714557600 报 cannot unmarshal number into … time.Time,null 保持零值。", t=tl(S(2)), mark=lidx(S(2), '/x?t=2024-05-01  ', '/x?t=2024-05-01+10:00:00', '/x?d=2024-02-30', 'JSON {"t":"2024-05-01"}', 'JSON {"t":1714557600}'), done=lidx(S(2), '/x?t=  ', '%2B08:00', 'JSON {"t":"2024-05-01T10:00:00Z"}', 'JSON {"t":null}'), kv=KV([['格式不符', 'parsing time … cannot parse'], ['空值', '保持零时间,不报错'], ['查询串里的 +', '要编码成 %2B,否则变成空格']], ['查询串里的 +'])),
    step("切片:重复的键(?multi=1&multi=2&multi=3)得到 [1 2 3];?multi=1,2,3 没写 collection_format 时整个字符串当一个整数解析,报 strconv.ParseInt: parsing \"1,2,3\": invalid syntax;collection_format 支持 csv(逗号)、ssv(空格)、tsv(制表符)、pipes(竖线)、multi;csv 与重复键可以混用(?csv=1&csv=2,3 得 [1 2 3]);default=7;8;9 在没传时给默认切片,传了 def=1 就是 [1];固定长度数组 [3]int 传 2 个值报 [\"1\" \"2\"] is not valid value for [3]int;?multi=(空值)得 [0],?strs=&strs= 得 [\"\" \"\"];字符串切片没写 collection_format 时 ?strs=a,b 就是一个元素 \"a,b\"。", t=tl(S(3)), mark=lidx(S(3), '/x?multi=1,2,3', '/x?arr=1,2  ', '/x?multi=  ', '/x?strs=a,b'), done=lidx(S(3), '/x?multi=1&multi=2&multi=3', '/x?csv=1,2,3', '/x?ssv=a+b+c', '/x?pipes=a|b|c', '/x?def=1'), kv=KV([['重复键', '[1 2 3],不需要 collection_format'], ['逗号分隔', '必须写 collection_format:"csv"'], ['空值', '整数切片得 [0]']], ['逗号分隔'])),
    step("类型转换错误的原文:?n=abc → strconv.ParseInt: parsing \"abc\": invalid syntax;溢出是 value out of range(int 的 99999999999999999999、uint8 的 256);uint8 收到 -1 是 invalid syntax;?b=maybe → ParseBool invalid syntax;?d=5+minutes → time: unknown unit \" minutes\";正常的 1m30s、1e3 都能解析。空值 ?n=&b=&f=&d= 全部当作零值,没有错误;?n=%2012%20 前后空格会被 TrimSpace 去掉,得到 12。", t=tl(S(4)), mark=lidx(S(4), '/x?n=abc', '/x?n=99999999999999999999', '/x?u=256', '/x?u=-1', '/x?b=maybe', '/x?d=5+minutes'), done=lidx(S(4), '/x?n=12&u=200', '/x?n=&b=&f=&d=', '/x?n=%2012%20'), kv=KV([['不是数字', 'ParseInt: invalid syntax'], ['溢出', 'value out of range'], ['空值', '零值,不报错'], ['前后空格', '非字符串类型会 TrimSpace']], ['空值'])),
    step("自定义类型:实现 UnmarshalParam(param string) error(BindUnmarshaler)后,Level 字段能从 ?lv=high 解出 3,未知值返回自己的错误(未知等级 \"ultra\"),切片 ?lvs=low&lvs=high 得 [1 3]。带 form 标签的 []Item(结构体切片)的每个值按 JSON 解码:?items={\"sku\":\"a\",\"n\":1}&items={…} 得到两个元素,?items=oops 报 invalid character 'o' looking for beginning of value。", t=tl(S(5)), mark=lidx(S(5), '/x?lv=ultra', '/x?items=oops'), done=lidx(S(5), '/x?lv=high', '/x?lvs=low&lvs=high', '/x?items={"sku"'), kv=KV([['UnmarshalParam', '自定义类型自己解析参数值'], ['[]struct', '每个值按 JSON 解码'], ['错误', '自己返回的 error 原样出现在 ShouldBind 的结果里']], ['UnmarshalParam'])),
]
A = mkartn('n30', 30, 'Gin,参数绑定,time.Time,切片,collection_format,Go,真实验证,动画演示',
    '在 Gin v1.12.0 里实测 time.Time、切片、嵌套类型的绑定:time_format / time_utc / time_location / unix 的时区结果(设进程时区为 America/New_York);查询串里的加号变空格;?multi=1,2,3 必须写 collection_format:"csv" 才能拆开;类型转换错误的原文;自定义类型实现 UnmarshalParam。',
    '查询串里的日期怎么写、时区跟谁走、逗号分隔的数组为什么绑不上、?n= 空值是不是报错?这篇把 time.Time、切片和常见类型转换在 form 绑定里的行为一项项实测,并看自定义类型怎么接管解析。',
    [('-04:00 / Z / +08:00', '不写时区 / time_utc:"1" / time_location 三种写法绑出的时区(进程时区 America/New_York)'), ('1,2,3 → 报错', '没写 collection_format 时,?multi=1,2,3 被当成一个整数解析'), ('空值 → 0', '?n=、?b=、?f=、?d= 都不报错,当作零值')],
    [('time.Time 与时区', '<p>form 绑定里的 <code>time.Time</code> 默认按 RFC3339,字符串里自带偏移就以它为准。自定义 <code>time_format</code> 又没有时区信息时,默认用 <code>time.Local</code>——同一份代码在不同机器上解出不同的时刻,所以要显式写 <code>time_utc:"1"</code> 或 <code>time_location</code>。<code>unix</code>、<code>unixmilli</code> 等格式把整数当时间戳,结果是 Local 时区表示的时间。</p>'),
     ('错误与空值', '<p>格式不符报 <code>parsing time … cannot parse …</code>;空值不报错,保持零时间(配合 <code>required</code> 才会失败)。URL 里没编码的 <code>+</code> 在查询串里是空格,所以带 <code>+08:00</code> 的 RFC3339 时间要把加号写成 <code>%2B</code>。JSON 里的 <code>time.Time</code> 只认 RFC3339 字符串,数字不行。</p>'),
     ('切片', '<p>重复的键是 form 里切片的“原生”写法。逗号、空格、竖线分隔必须用 <code>collection_format</code> 声明(csv / ssv / tsv / pipes),否则整个字符串当一个元素(整数切片会因此报错)。<code>default=7;8;9</code> 用分号分隔默认值。固定长度的数组必须正好给够元素。空值对整数切片会得到 <code>[0]</code>,要小心。</p>'),
     ('类型转换', '<p>错误信息都是 <code>strconv</code> 的原文,直接返回给用户并不友好,通常要自己翻译。空值一律当零值,不报错;非字符串类型会先去掉前后空格。</p>'),
     ('自定义类型', '<p>字段类型实现 <code>UnmarshalParam(string) error</code> 就可以接管解析(<code>BindUnmarshaler</code>),适合枚举、ID 之类;返回的错误原样成为绑定的错误。结构体切片则是每个参数值按 JSON 解码。</p>')],
    steps,
    [ENV_N_GIN + '。时间实验用环境变量 TZ=America/New_York(第二节 TZ=UTC)切换 time.Local;请求用 httptest 直接调用 ServeHTTP;每种情形各一次',
     '没有验证:time_format 对 RFC1123 等其它布局的行为(只试了 RFC3339 / 2006-01-02 / unix);夏令时边界的时间解析;parser=encoding.TextUnmarshaler 选项(源码里有,没有跑);multipart 表单里的数组与时间(规则相同,没有单独验证);map 类型字段的绑定'],
    '时间、切片与类型转换')
